/**
 * Track: a song in the catalog — uploaded by a creator, added by staff,
 * imported from a royalty-free library, or generated by AI (PRD §13 `tracks`).
 *
 * Audio files live in object storage and are referenced by storage KEY (never
 * a public URL): listeners get short-lived signed URLs from the stream endpoint.
 */
import mongoose from "mongoose";
import {
  PROCESSING_STATES,
  RELEASE_INTENTS,
  TRACK_ADDED_VIA,
  TRACK_SOURCE,
  TRACK_STATUS,
} from "../config/constants.js";

const audioFormatSchema = new mongoose.Schema(
  {
    bitrateKbps: { type: Number, required: true }, // e.g. 128, 320
    codec: { type: String, required: true }, // e.g. "mp3"
    key: { type: String, required: true }, // storage key of the rendition
    sizeBytes: { type: Number, default: null },
  },
  { _id: false }
);

const trackSchema = new mongoose.Schema(
  {
    title: { type: String, required: true, trim: true, maxlength: 150 },
    artistId: { type: mongoose.Schema.Types.ObjectId, ref: "ArtistProfile", required: true },
    albumId: { type: mongoose.Schema.Types.ObjectId, ref: "Album", default: null },
    uploadedBy: { type: mongoose.Schema.Types.ObjectId, ref: "User", required: true },

    audio: {
      sourceKey: { type: String, default: null }, // the uploaded original (kept for reprocessing)
      formats: { type: [audioFormatSchema], default: [] }, // transcoded versions
      durationSec: { type: Number, default: 0, min: 0 },
      waveform: { type: [Number], default: [] }, // 0–1 peaks for the player's waveform
    },
    coverUrl: { type: String, default: null }, // public URL of the processed cover
    coverKey: { type: String, default: null }, // storage key behind coverUrl (for cleanup)
    coverSourceKey: { type: String, default: null }, // uploaded cover waiting to be processed

    genres: { type: [String], default: [] },
    vibes: { type: [String], default: [] },
    mood: { type: String, trim: true, default: null },
    bpm: { type: Number, min: 20, max: 300, default: null },
    energy: { type: Number, min: 0, max: 1, default: null },
    language: { type: String, trim: true, default: null },
    explicit: { type: Boolean, default: false },
    lyrics: { type: String, default: "" },

    source: { type: String, enum: TRACK_SOURCE, default: "upload" },
    addedVia: { type: String, enum: TRACK_ADDED_VIA, default: "creator" },
    rightsConfirmed: { type: Boolean, default: false }, // PRD CRT-6
    // Royalty-free imports keep their licence and credit (e.g. CC BY)
    license: {
      name: { type: String, default: null },
      url: { type: String, default: null },
      attribution: { type: String, default: null },
    },
    external: {
      provider: { type: String, default: null }, // "ccmixter" | "jamendo"
      id: { type: String, default: null },
      url: { type: String, default: null },
    },

    status: { type: String, enum: TRACK_STATUS, default: "processing" },
    releaseIntent: { type: String, enum: RELEASE_INTENTS, default: "publish" },
    scheduledAt: { type: Date, default: null },
    publishedAt: { type: Date, default: null },
    featured: { type: Boolean, default: false },

    processing: {
      state: { type: String, enum: PROCESSING_STATES, default: "queued" },
      error: { type: String, default: null },
      attempts: { type: Number, default: 0 },
      finishedAt: { type: Date, default: null },
    },

    playCount: { type: Number, default: 0, min: 0 },
    likeCount: { type: Number, default: 0, min: 0 },
  },
  { timestamps: true }
);

// Indexes from PRD §13 "Important indexes"
trackSchema.index({ genres: 1 });
trackSchema.index({ "audio.sourceKey": 1 });
trackSchema.index({ coverSourceKey: 1 }, { sparse: true });
trackSchema.index({ vibes: 1 });
trackSchema.index({ status: 1 });
trackSchema.index({ status: 1, scheduledAt: 1 });
trackSchema.index({ artistId: 1, createdAt: -1 });
trackSchema.index({ uploadedBy: 1, createdAt: -1 });
// Our `language` field holds values like "hindi", which MongoDB would otherwise read as the
// text-search language and reject — point the override at a field we never set.
trackSchema.index(
  { title: "text" },
  { name: "title_search", default_language: "none", language_override: "textSearchLanguage" }
);
// One copy per imported external track
trackSchema.index(
  { "external.provider": 1, "external.id": 1 },
  { unique: true, partialFilterExpression: { "external.id": { $type: "string" } } }
);

export const Track = mongoose.model("Track", trackSchema);
